text = '# web\nDjango==5.0.1\n\nrequests==2.31.0\n# data\npandas==2.2.2'
reqs = {}
for line in text.splitlines():
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    name, version = line.split('==')
    reqs[name.lower()] = version
print(reqs)

def fake_get(url):
    # stands in for requests.get(url) in this offline app
    return {'status_code': 200,
            'headers': {'content-type': 'text/plain'},
            'text': 'Hello from ' + url}

response = fake_get('https://example.com/hello.txt')
print(response['status_code'], response['headers']['content-type'])
print(response['text'])

def describe(code):
    if 200 <= code < 300:
        return 'success'
    if 400 <= code < 500:
        return 'client error'
    if code >= 500:
        return 'server error'
    return 'other'

print([describe(c) for c in [200, 404, 503, 301]])

